package io.github.kxyr0.echodialogue.forge.client.ui.image;

import java.util.Objects;
import net.minecraft.resources.ResourceLocation;

/**
 * Deterministic low-level blit command generated by a UI image mode.
 */
public record UiImageDrawCommand(
        ResourceLocation texture,
        UiImageRenderMode mode,
        int x,
        int y,
        int targetWidth,
        int targetHeight,
        int sourceX,
        int sourceY,
        int sourceWidth,
        int sourceHeight,
        int textureWidth,
        int textureHeight
) {
    public UiImageDrawCommand {
        Objects.requireNonNull(texture, "texture");
        Objects.requireNonNull(mode, "mode");
        requirePositive(targetWidth, "targetWidth");
        requirePositive(targetHeight, "targetHeight");
        requirePositive(sourceWidth, "sourceWidth");
        requirePositive(sourceHeight, "sourceHeight");
        requirePositive(textureWidth, "textureWidth");
        requirePositive(textureHeight, "textureHeight");
    }

    private static void requirePositive(int value, String name) {
        if (value <= 0) {
            throw new IllegalArgumentException("UI_IMAGE_REGION_INVALID: " + name + " must be positive.");
        }
    }
}
